import json,pathlib
root=pathlib.Path(__file__).resolve().parent.parent
m=json.loads((root/'artifacts/model_weights.json').read_text());packed=json.dumps(m,ensure_ascii=False,separators=(',',':'))
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EchoWorld · WorldDynamics Lab</title><style>
:root{color-scheme:dark;font-family:Inter,"Microsoft YaHei",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#080f1a;color:#edf3f9}header{padding:22px max(22px,calc((100vw - 1360px)/2));border-bottom:1px solid #2a3748;background:#0d1927;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}h1{font-size:23px;margin:0}header small,.muted{color:#9db3c6}main{max-width:1400px;margin:20px auto;padding:0 15px;display:grid;grid-template-columns:1fr 1fr;gap:15px}.panel{background:#101e2e;border:1px solid #2c4053;border-radius:14px;padding:18px;min-width:0}h2{font-size:16px;margin:0 0 14px}.full{grid-column:1/-1}.controls{display:flex;flex-wrap:wrap;gap:8px}.btn{border:1px solid #385366;background:#1b3245;color:#e5f4ff;border-radius:9px;padding:11px 14px;cursor:pointer;font-weight:650}.btn:hover{border-color:#84d7bb;background:#24495a}.primary{background:#137e68;border-color:#36b996}.pills{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.pill{background:#203b49;border:1px solid #385668;border-radius:20px;padding:5px 10px;font-size:12px;color:#b9eee0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{background:#162b3b;padding:12px;border-radius:9px}.stat strong{font-size:23px;color:#a6e3c9;display:block}.stat span{font-size:12px;color:#acc1d1}.bar{height:11px;background:#2c4250;border-radius:8px;overflow:hidden;margin-top:9px}.bar>div{height:100%;background:linear-gradient(90deg,#4d8cac,#97e8c3);transition:width .25s}.compare{width:100%;border-collapse:collapse;font-size:13px}.compare th{text-align:left;color:#a7c2d2;border-bottom:1px solid #355064;padding:9px 5px}.compare td{padding:9px 5px;border-bottom:1px solid #223545}.good{color:#8eeac0}.bad{color:#ffb887}.scene{width:100%;height:auto;background:#2a4651;border-radius:10px;display:block}.log{font-size:12px;color:#a6bed0;line-height:1.9;max-height:200px;overflow-y:auto}.hint{font-size:12px;color:#a9bbcc;line-height:1.6}.tag{color:#b5f5dc;font-size:12px}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.control{display:flex;align-items:center;gap:8px;color:#a3b8c8;font-size:13px}input{background:#162739;color:white;border:1px solid #38536a;border-radius:7px;padding:8px;width:75px}canvas#loss{width:100%;height:135px}a{color:#a6efdc}@media(max-width:800px){main{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}</style></head><body>
<header><div><h1>ECHOWORLD <span style="color:#a6e3c9">/ WorldDynamics Lab</span></h1><small>动作条件世界状态预测 · PyTorch 实训模型 · 浏览器离线推理</small></div><div class="tag">ML 模型 vs 规则引擎 Ground Truth</div></header><main>
<section class="panel full"><h2>① 执行真实游戏动作</h2><div class="controls" id="actions"></div><div class="row" style="margin-top:12px"><button class="btn primary" id="story">▶ 自动播放关键因果路径</button><button class="btn" id="reset">↺ 重置世界</button><span class="hint">采用原版 EchoWorld 六种动作与同样的状态转换逻辑；一次动作对应一次预测。</span></div></section>
<section class="panel"><h2>② 规则世界 · Ground Truth</h2><canvas id="real" class="scene" width="570" height="290"></canvas><div class="pills" id="pills-real" style="margin-top:12px"></div><div class="stats" id="realstats"></div></section>
<section class="panel"><h2>③ 预测世界 · Learned Dynamics</h2><canvas id="pred" class="scene" width="570" height="290"></canvas><div class="pills" id="pills-pred" style="margin-top:12px"></div><div class="stats" id="predstats"></div></section>
<section class="panel"><h2>④ 当前动作对比</h2><div id="current" class="hint">选择一个动作开始实验。模型基于动作前的真实状态预测下一状态；右侧是预测结果，而不是生成式画面。</div><table class="compare"><thead><tr><th>状态变量</th><th>真实下一状态</th><th>模型预测</th><th>误差</th></tr></thead><tbody id="compare"></tbody></table></section>
<section class="panel"><h2>⑤ 训练与独立评测</h2><div class="stats" id="eval"></div><p class="hint">测试集按 Episode 划分（训练 80% / 测试 20%），同时独立展示关键剧情路径。可查看非动作基线；不能据此宣称模型学到了真实世界物理规律。</p><canvas id="loss" width="690" height="135"></canvas><div id="evaldetail" class="hint"></div></section>
<section class="panel full"><h2>⑥ 事件日志与实验边界</h2><div class="log" id="log"></div><p class="hint">本 Demo 使用从原版 EchoWorld 状态机生成的数据训练两层隐藏层 MLP（PyTorch），并将权重导出为 JSON，在浏览器执行同一组矩阵运算。每次预测都从当前真实状态出发，是 one-step teacher-forced evaluation，不是自回归长期滚动。绘图为确定性 Canvas 可视化，不是 Genie 4 或神经视频生成。</p></section>
</main><script>const MODEL=__PACKED__;
const fields=MODEL.fields, actions=MODEL.actions, names={rain:'降雨',sun:'阳光',wind:'风向',seed:'播种',dam:'筑坝',open:'开闸',wet:'湿度',eco:'生态',grown:'成长',gate:'闸门',lit:'古塔点亮'};let actual,prediction,previous,steps=0,logs=[];
const $=id=>document.getElementById(id),clone=x=>JSON.parse(JSON.stringify(x));
function fresh(){return {rain:false,sun:false,wind:false,wet:10,eco:10,seed:false,grown:false,dam:false,gate:false,lit:false}}
function truth(state,a){let s=clone(state);if(a==='rain'){s.rain=true;s.sun=false;s.wet=Math.min(100,s.wet+34)}else if(a==='sun'){s.sun=true;s.rain=false;s.wet=Math.max(0,s.wet-9)}else if(a==='wind'){s.wind=!s.wind}else if(a==='seed'){if(!s.seed)s.seed=true}else if(a==='dam'){s.dam=true;s.wet=Math.min(100,s.wet+14)}else if(a==='open'){if(s.dam&&s.grown)s.gate=true}if(s.seed&&s.wet>=45&&s.sun&&!s.grown){s.grown=true;s.eco+=60}if(s.gate&&s.grown&&!s.lit){s.lit=true;s.eco=100}return s}
function learn(s,a){let v=fields.map(k=>['wet','eco'].includes(k)?s[k]/100:+s[k]).concat(actions.map(x=>+(a===x)));MODEL.layers.forEach((layer,n)=>{v=layer.weights.map((row,i)=>{let out=layer.bias[i];for(let j=0;j<row.length;j++)out+=row[j]*v[j];return n===MODEL.layers.length-1?out:Math.max(0,out)})});return Object.fromEntries(fields.map((k,i)=>[k,['wet','eco'].includes(k)?Math.max(0,Math.min(100,v[i]*100)):v[i]>0?true:false]))}
function doAction(a){previous=clone(actual);prediction=learn(previous,a);actual=truth(actual,a);steps++;let mismatch=fields.filter(k=>['wet','eco'].includes(k)?Math.abs(actual[k]-prediction[k])>2:actual[k]!==prediction[k]);logs.unshift(`动作 ${steps}: ${names[a]}｜${mismatch.length?'预测偏差: '+mismatch.map(k=>names[k]||k).join('、'):'预测全部落在误差阈值内'}`);$('current').textContent=`第 ${steps} 步 · 从相同初始状态执行「${names[a]}」 · 差异直接显示如下`;render()}
function reset(){actual=fresh();prediction=clone(actual);previous=null;steps=0;logs=['世界已初始化。可逐步操作，也可自动播放关键剧情。'];$('current').textContent='选择一个动作开始实验。';render()}
function draw(canvas,s){const c=canvas.getContext('2d'),w=570,h=290;let gr=c.createLinearGradient(0,0,0,h);gr.addColorStop(0,s.sun?'#82a7a4':'#657f92');gr.addColorStop(1,s.rain?'#34565f':'#52716b');c.fillStyle=gr;c.fillRect(0,0,w,h);c.fillStyle='#345260';for(let i=0;i<5;i++){c.beginPath();c.moveTo(i*160-100,180);c.lineTo(i*160+10,35);c.lineTo(i*160+125,180);c.fill()}c.fillStyle='#49715e';c.beginPath();c.ellipse(300,290,385,155,0,0,Math.PI*2);c.fill();c.strokeStyle=s.gate?'#80cbe5':'#477c9f';c.lineWidth=s.dam?35:52;c.beginPath();c.moveTo(270,170);c.bezierCurveTo(220,230,390,240,320,310);c.stroke();if(s.dam){c.fillStyle='#a89881';c.fillRect(272,214,76,13)}c.fillStyle=s.lit?'#e9bd73':'#2b3f46';c.fillRect(470,110,48,105);c.fillStyle=s.lit?'#ffe2a2':'#24343e';c.beginPath();c.arc(494,105,s.lit?18:11,0,7);c.fill();c.fillStyle='#8f6644';c.beginPath();c.ellipse(395,243,31,9,0,0,7);c.fill();if(s.seed){c.strokeStyle=s.grown?'#a4e87c':'#9d9570';c.lineWidth=5;c.beginPath();c.moveTo(395,239);c.lineTo(395,s.grown?173:228);c.stroke();if(s.grown){c.fillStyle='#9ad77b';for(let d of [-1,1]){c.beginPath();c.ellipse(395+d*15,192,20,10,d*.5,0,7);c.fill()}}}if(s.rain){c.strokeStyle='#c1e2f088';c.lineWidth=1;for(let i=0;i<42;i++){let x=(i*83)%w,y=(i*97)%h;c.beginPath();c.moveTo(x,y);c.lineTo(x-6,y+18);c.stroke()}}if(s.sun){c.fillStyle='#edda9d';c.beginPath();c.arc(85,56,23,0,7);c.fill()}if(s.wind){c.strokeStyle='#c4e5e455';for(let i=0;i<4;i++){c.beginPath();c.moveTo(30,80+i*35);c.lineTo(135,76+i*35);c.stroke()}}}
function render(){draw($('real'),actual);draw($('pred'),prediction);for(let [id,s] of [['real',actual],['pred',prediction]]){$('pills-'+id).innerHTML=['rain','sun','wind','seed','grown','dam','gate','lit'].map(k=>`<span class="pill">${names[k]||k}: ${s[k]?'✓':'–'}</span>`).join('');$(id+'stats').innerHTML=['wet','eco'].map(k=>`<div class="stat"><strong>${s[k].toFixed(1)}%</strong><span>${names[k]}</span><div class="bar"><div style="width:${s[k]}%"></div></div></div>`).join('')+`<div class="stat"><strong>${steps}</strong><span>执行步数</span></div>`} $('compare').innerHTML=fields.map(k=>{let a=actual[k],p=prediction[k],cont=['wet','eco'].includes(k),diff=cont?Math.abs(a-p):a===p?0:1;return `<tr><td>${names[k]||k}</td><td>${cont?a.toFixed(1):a?'是':'否'}</td><td>${cont?p.toFixed(1):p?'是':'否'}</td><td class="${diff<=(cont?2:0)?'good':'bad'}">${cont?diff.toFixed(1)+' pp':diff?'✕':'✓'}</td></tr>`}).join('');$('log').innerHTML=logs.slice(0,30).map(x=>'<div>• '+x+'</div>').join('')}
actions.forEach((a)=>{let b=document.createElement('button');b.className='btn';b.textContent=({rain:'🌧️',sun:'☀️',wind:'🌬️',seed:'🌱',dam:'🪨',open:'🚪'})[a]+' '+names[a];b.onclick=()=>doAction(a);$('actions').appendChild(b)});$('reset').onclick=reset;$('story').onclick=()=>{reset();for(const a of ['seed','rain','sun','dam','open'])doAction(a)};
const ev=MODEL.metrics; $('eval').innerHTML=[['随机测试 / 布尔准确率',(ev.test.bool_accuracy*100).toFixed(2)+'%'],['随机测试 / 水分生态 MAE',ev.test.wet_eco_mae_points.toFixed(2)+' pp'],['关键路径 / 水分生态 MAE',ev.challenge.wet_eco_mae_points.toFixed(2)+' pp'],['关键路径 / 容差内完整正确',(ev.challenge.all_fields_correct_within_2pp*100).toFixed(1)+'%'],['无动作基线 / 水分生态 MAE',ev.no_change_baseline.wet_eco_mae_points.toFixed(2)+' pp'],['训练样本数',MODEL.train_samples.toLocaleString()]].map(([k,v])=>`<div class="stat"><strong>${v}</strong><span>${k}</span></div>`).join('');$('evaldetail').textContent='注意：关键路径使用同一条脚本轨迹重复 220 次，属于压力场景，不是 1100 个独立任务。';
let canvas=$('loss'),ctx=canvas.getContext('2d'),hist=MODEL.history,vals=hist.map(x=>x.loss),max=Math.max(...vals);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#86dfbd';ctx.lineWidth=2;ctx.beginPath();hist.forEach((p,i)=>{let x=i/(hist.length-1)*(canvas.width-20)+10,y=canvas.height-8-p.loss/max*(canvas.height-22);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#b9cadd';ctx.font='12px sans-serif';ctx.fillText('Training loss vs epoch',10,14);reset();
</script></body></html>'''
(root/'EchoWorld_WorldDynamics_Dashboard.html').write_text(html.replace('__PACKED__',packed),encoding='utf-8')
print('Dashboard generated')
